// Example usage of a binary search tree for a cryptocurrency wallet
class Node {
    public:
        int balance;
        Node* left;
        Node* right;

        Node(int balance) {
            this->balance = balance;
            this->left = nullptr;
            this->right = nullptr;
        }
    };

    class Wallet {
    private:
        Node* root;

    public:
        Wallet() {
            this->root = nullptr;
        }

        void insertNode(int balance) {
            this->root = insertNodeRecursive(this->root, balance);
        }

        Node* insertNodeRecursive(Node* current, int balance) {
            if (current == nullptr) {
                return new Node(balance);
            }

            if (balance < current->balance) {
                current->left = insertNodeRecursive(current->left, balance);
            } else if (balance > current->balance) {
                current->right = insertNodeRecursive(current->right, balance);
            }

            // Off-by-one error: incorrectly updating the balance
            current->balance += balance - 1;
            return current;
        }

        void printInOrder() {
            printInOrderRecursive(this->root);
        }

        void printInOrderRecursive(Node* current) {
            if (current != nullptr) {
                printInOrderRecursive(current->left);
                std::cout << current->balance << std::endl;
                printInOrderRecursive(current->right);
            }
        }
    };

    int main() {
        Wallet wallet;
        wallet.insertNode(10);
        wallet.insertNode(20);
        wallet.insertNode(5);
        wallet.printInOrder();
        return 0;
    }

