// Custom hash table implementation for student grades
class StudentGrade {
    public:
        StudentGrade(std::string name, double grade) :
            name_(name),
            grade_(grade) {}
        std::string name_;
        double grade_;
};

class HashTable {
    private:
        static const int tableSize = 128;
        std::list<StudentGrade>* table;
    public:
        HashTable() {
            table = new std::list<StudentGrade>[tableSize];
        }
        ~HashTable() {}
        void insert(std::string name, double grade) {
            int index = std::hash<std::string>{}(name) % tableSize;
            table[index].push_back(StudentGrade(name, grade));
        }
};
int main() {
    HashTable hashTable;
    hashTable.insert("John Doe", 90.0);
    hashTable.insert("Jane Doe", 85.0);
    return 0;
}

