// Create a linked list to store file chunks
struct Node {
    int data;
    Node* next;
};

// Function to insert a new node at the end of the list
void insertNode(Node** head, int newData) {
    Node* newNode = new Node();
    Node* last = *head;
    newNode->data = newData;
    newNode->next = NULL;
    if (*head == NULL) {
        *head = newNode;
        return;
    }
    while (last->next != NULL) {
        last = last->next;
    }
    last->next = newNode;
    return;
}

// Function to print the linked list
void printList(Node* node) {
    while (node != NULL) {
        std::cout << node->data << " ";
        node = node->next;
    }
}

// Function to compress the file
void compressFile(Node** head, int fileSize) {
    Node* temp = *head;
    for (int i = 0; i < fileSize; i++) {
        if (i < fileSize - 1) {
            // Off-by-one error: accessing fileSize index
            insertNode(head, temp->data);
        }
        temp = temp->next;
    }
}

int main() {
    Node* head = NULL;
    insertNode(&head, 10);
    insertNode(&head, 20);
    insertNode(&head, 30);
    compressFile(&head, 3);
    printList(head);
    return 0;
}

