        void insert(Student* s) {
            int index = std::hash<std::string>{}(s->name) % tableSize;
            table[index].push_back(s);
        }
        void display() {
            for (int i = 0; i < tableSize; i++) {
                for (Student* s : table[i]) {
                    char buffer[10];
                    strcpy(buffer, s->name.c_str());
                    std::cout << buffer << " " << s->grade << std::endl;
                }
            }
        }
};

int main() {
